failures = []


def cmp(path, a, b):
    if type(a) is not type(b):
        failures.append(f"{path}: TYPE {type(a).__name__} != {type(b).__name__}")
        return
    if isinstance(a, dict):
        ka, kb = list(a), list(b)
        if ka != kb:
            failures.append(f"{path}: KEY ORDER {ka} != {kb}")
        for k in ka:
            if k in b:
                cmp(f"{path}[{k!r}]", a[k], b[k])
        return
    if isinstance(a, list):
        if len(a) != len(b):
            failures.append(f"{path}: LEN {len(a)} != {len(b)}")
        for i, (x, y) in enumerate(zip(a, b)):
            cmp(f"{path}[{i}]", x, y)
        return
    if isinstance(a, tuple):
        if len(a) != len(b):
            failures.append(f"{path}: TLEN {len(a)} != {len(b)}")
        for i, (x, y) in enumerate(zip(a, b)):
            cmp(f"{path}({i})", x, y)
        return
    if isinstance(a, float):
        if a != b or (math.isnan(a) != math.isnan(b)):
            failures.append(f"{path}: FLOAT {a!r} != {b!r}")
